using System;using System.Configuration;using System.Web;using System.Web.UI;namespace ZavaLoanPortal{public partial class Login:Page{protected void Page_Load(object sender,EventArgs e){var returnUrl=(Request.QueryString["ReturnUrl"]??"~/Default.aspx").Trim();if(Request.IsAuthenticated){Response.Redirect(ResolveClientUrl(returnUrl),false);Context.ApplicationInstance.CompleteRequest();return;}var auth=ConfigurationManager.AppSettings["AuthGatewayLoginUrl"]??"http://localhost:8000/Login.aspx";lnkAuthGateway.NavigateUrl=auth+"?ReturnUrl="+HttpUtility.UrlEncode(ResolveClientUrl(returnUrl));lblMessage.Text="Authentication is handled by ZavaAuthGateway.";}}}
